"""Builds the 20 DRAFT scenario specifications (original master list, in order). Six are decision graphs where read sources support the branching;
fourteen are outlines that list only the nursing actions the sources support and the sources still needed. Fictional patients; no dosing; no review claims."""
import json, os
OUT = os.path.dirname(os.path.abspath(__file__))
BANNER = "DRAFT, NOT clinically reviewed. Fictional scenario specification; never imported, published or shown to learners."
MASTER = ["Septic shock","Cardiogenic shock","Acute respiratory deterioration","Ventilator alarm","Sudden oxygen desaturation","Accidental extubation","Raised intracranial pressure","Acute seizure","Postoperative bleeding","Hypoglycemia","Severe hyperkalemia","Acute arrhythmia","Cardiac arrest","Transfusion reaction","CRRT circuit complication","Acute hypotension","Delirium and agitation","Aspiration event","Anaphylaxis","Acute neurological deterioration"]
def src(i, r, u): return {"id": i, "read": r, "use": u}
def ob(key, label, value, unit=None):
    o = {"key": key, "label": label, "value": value}
    if unit: o["unit"] = unit
    return o
def op(text, pts, nxt, scope, fb, cons, sup, *srcs): return {"text": text, "points": pts, "next": nxt, "scope": scope, "feedback": fb, "consequence": cons, "support": sup, "sources": list(srcs)}
def act(text, scope, sup, *srcs): return {"text": text, "scope": scope, "support": sup, "sources": list(srcs)}
def write(n, d):
    base = {"scenario_id": f"SC-{n:02d}", "number": n, "title": MASTER[n-1], "status": "DRAFT", "origin": "ai_generated", "clinically_reviewed": False, "clinical_reviewers": [], "banner": BANNER, "fictional_patient": True}
    base.update(d)
    slug = MASTER[n-1].lower().replace(" ", "-")
    json.dump(base, open(os.path.join(OUT, f"SC-{n:02d}-{slug}.json"), "w"), indent=1, ensure_ascii=False)
GAPS_STD = ["No published clinical scenario may exist until the review phase: this is a specification only.", "The branching content, consequences and scoring are the author's reading of the cited sources and have had no clinical review."]
PERM = ["Cited sources are paraphrased only; see the licensing register for each source's reproduction status."]
